// The generated CSS. Every `<layer>.config.json` lays tokens out as `src/theme/tokens/<layer>/*.css` plus a barrel,
// and may describe preview files: the tokens a mode changes, under the mode's selector.

import assert from 'node:assert/strict';
import { declaration, literal } from './dtcg.mjs';

const THEME_DIR = 'src/theme/tokens';
const PREVIEW_DIR = 'design-system/tokens/preview';

const header = (tokens, config) => `/*
 * GENERATED by scripts/tokens/generate.mjs from design-system/tokens/source/${tokens} and
 * ${config}. Do not edit: change those files and run \`pnpm tokens:generate\`.
 */`;

const globToRegExp = (pattern) =>
    new RegExp(
        `^${pattern
            .split('.')
            .map((part) => (part === '*' ? '([^.]+)' : part.replace(/[-/\\^$+?()|[\]{}]/g, '\\$&')))
            .join('\\.')}$`,
    );

// token path -> CSS custom property, by the first matching `cssNames` rule; undefined without one.
const createNameOf = (cssNames) => {
    const rules = cssNames.map(([pattern, template]) => [globToRegExp(pattern), template]);
    return (path) => {
        for (const [regexp, template] of rules) {
            const match = path.match(regexp);
            if (match != null) {
                return template.replace(/\$(\d)/g, (_, n) => match[Number(n)]);
            }
        }
    };
};

const block = ([selector, lines]) => `${selector} {\n${lines.map((line) => `    ${line}`).join('\n')}\n}`;

// Kit-relative path -> generated text. `layers`: layer name -> its config. `modeTokens`: the documents of a mode ->
// the tokens with those documents merged over `tokens`. Fails unless every token has one CSS name of its own and is
// placed exactly once.
export const renderCss = ({ tokens, layers, modeTokens }) => {
    const nameOf = createNameOf(Object.values(layers).flatMap(({ cssNames }) => Object.entries(cssNames)));
    const varOf = (path) => {
        const name = nameOf(path);
        assert(name, `No CSS name for token ${path} (cssNames)`);
        return name;
    };
    const placed = new Map(); // CSS name -> token path, in output order
    const files = new Map();
    const writeDir = (dir, texts, sources) => {
        for (const [file, text] of texts) {
            files.set(`${dir}/${file}`, `${header(...sources)}\n\n${text}\n`);
        }
        const barrel = texts.map(([file]) => `@import "./${file}";`).join('\n');
        files.set(`${dir}/index.css`, `${header(...sources)}\n\n${barrel}\n`);
    };

    for (const [layer, config] of Object.entries(layers)) {
        // A line ending in `;` is CSS; any other line is a token path: that token, or every token under that group.
        const renderLine = (line) => {
            if (line.endsWith(';')) {
                return [line];
            }
            const paths = [...tokens.keys()].filter((path) => path === line || path.startsWith(`${line}.`));
            assert(paths.length > 0, `${layer}.config.json: no token at or under ${line}`);
            return paths.map((path) => {
                const name = varOf(path);
                assert(placed.get(name) !== path, `${layer}.config.json: token ${path} is placed twice`);
                assert(!placed.has(name), `${path} and ${placed.get(name)} share the CSS name ${name}`);
                placed.set(name, path);
                return declaration(name, tokens.get(path), varOf);
            });
        };
        const texts = Object.entries(config.files).map(([file, blocks]) => [
            file,
            Object.entries(blocks)
                .map(([selector, lines]) => block([selector, lines.flatMap(renderLine)]))
                .join('\n\n'),
        ]);
        writeDir(`${THEME_DIR}/${layer}`, texts, [`${layer}.tokens.json`, `${layer}.config.json`]);
    }
    const paths = new Set(placed.values());
    const missing = [...tokens.keys()].filter((path) => !paths.has(path));
    assert.equal(missing.length, 0, `The layout places no CSS for: ${missing.join(', ')}`);

    // A preview file: per mode selector, every placed token whose value differs from the default, as a literal.
    const previews = Object.entries(layers).flatMap(([layer, config]) =>
        Object.entries(config.preview ?? {}).map(([file, modes]) => {
            const blocks = Object.entries(modes).map(([selector, documents]) => {
                const mode = modeTokens(documents);
                const stray = [...mode.keys()].filter((path) => !tokens.has(path) && nameOf(path));
                assert.equal(stray.length, 0, `${layer}.config.json: not in the default theme: ${stray.join(', ')}`);
                const changed = [...placed].filter(([, path]) => literal(mode, path) !== literal(tokens, path));
                return [selector, changed.map(([name, path]) => `${name}: ${literal(mode, path)};`)];
            });
            return [file, blocks.map(block).join('\n\n')];
        }),
    );
    if (previews.length > 0) {
        writeDir(PREVIEW_DIR, previews, ['modes/', 'the `preview` of the *.config.json files']);
    }
    return files;
};
